import { Activity, Brain, Clock, Pen, Search, Users, Wrench, type LucideIcon } from "lucide-react";

// --- Streaming (per-conversation `message_streaming` events) ---

export const STREAM_STATUSES = ["started","streaming","complete","cancelled"] as const;
export type StreamStatus = (typeof STREAM_STATUSES)[number];

export const STREAM_PHASES = ["thinking","tool_call","writing","analyzing","queued","waiting"] as const;
export type StreamPhase = (typeof STREAM_PHASES)[number];

// --- Global per-agent activity (`agent_activity_changed` events) ---
// Same vocabulary as StreamPhase plus "working" (has an active task but not
// streaming) and minus "queued" (an online/offline signal, not an activity).

export const AGENT_ACTIVITIES = ["thinking","tool_call","writing","analyzing","waiting","working"] as const;
export type AgentActivity = (typeof AGENT_ACTIVITIES)[number];

// --- Presence / runtime ---

export const PRESENCES = ["online_local","offline"] as const;
export type AgentPresence = (typeof PRESENCES)[number];

export const RUNTIMES = ["local","org_host"] as const;
export type AgentRuntime = (typeof RUNTIMES)[number];

export const PRESENCE_MODES = ["always_on","wake_on_demand","manual"] as const;
export type PresenceMode = (typeof PRESENCE_MODES)[number];

