// --- Timing constants ---

// Client-side decay for typing indicators (no explicit stop event).
export const TYPING_TIMEOUT_HUMAN_MS = 3000;
export const TYPING_TIMEOUT_AGENT_MS = 30000;

// A stream with no update for this long is orphaned (bridge died and the
// backend TimeoutServer's cancel was missed). Must stay above the backend's
// worst-case forced-cancel latency.
export const STALE_STREAM_MS = 75000;

// How long a completed stream bubble lingers before clearing.
export const STREAM_COMPLETE_LINGER_MS = 3000;

// Reaper sweep cadence for the above.
export const STREAM_SWEEP_INTERVAL_MS = 10000;
